mapper.select:
select * from user_long_term_memory
where patient_id_hash = #{patientIdHash}
  and memory_type = #{memoryType}
  and active = 1
order by updated_at desc, id desc

mapper.update:
update user_long_term_memory
set active = 0
where id = #{id}
  and patient_id_hash = #{patientIdHash}

